    "precision-attack":    {name:"Точная атака", desc:"Промахнувшись атакой, тратите кость превосходства, бросаете её и добавляете к броску атаки, потенциально превращая промах в попадание."},
    "pushing-attack":      {name:"Толкающая атака", desc:"Попав атакой, добавляете кость превосходства к урону; цель ≤ Большого проходит спасбросок Силы или отталкивается до 15 фт."},
    "rally":               {name:"Сплочение", desc:"Бонусным действием тратите кость превосходства: союзник в 30 фт получает временные ХП = кость + половина уровня воина (округление вниз)."},
    "riposte":             {name:"Ответный удар", desc:"Реакцией, когда существо промахивается по вам рукопашной атакой, тратите кость превосходства и совершаете рукопашную атаку по нему; при попадании добавляете кость к урону."},
    "sweeping-attack":     {name:"Широкая атака", desc:"Попав рукопашной атакой, тратите кость превосходства: выбираете другое существо в 5 фт от цели и в досягаемости — при том же результате броска оно получает урон, равный кости превосходства."},
    "trip-attack":         {name:"Опрокидывающая атака", desc:"Попав атакой оружием или безоружным ударом, добавляете кость превосходства к урону; цель ≤ Большого проходит спасбросок Силы или получает состояние лежащий ничком."},
    "bait-and-switch":     {name:"Подмена", desc:"В свой ход, находясь в 5 фт от существа, тратите кость превосходства и меняетесь с ним местами (существо согласно, без провоцированных атак); вы или оно получаете бонус к КД, равный кости, до начала вашего следующего хода."},
